<script setup lang="ts">const{recent,pending,loadRecent,clearRecent}=useAccount();useHead({title:"بازدیدهای اخیر — هفت‌سو",meta:[{name:"robots",content:"noindex,nofollow"}]});onMounted(()=>void loadRecent());</script>
<template><AccountShell title="بازدیدهای اخیر" description="حداکثر ۱۰۰ آگهی بازدیدشده در ۹۰ روز گذشته نگهداری می‌شود."><template #action><button v-if="recent.length" class="button button-secondary" type="button" @click="clearRecent">پاک‌کردن تاریخچه</button></template><UiState v-if="pending&&!recent.length" kind="loading" title="در حال دریافت تاریخچه" description="بازدیدها در حال بارگذاری هستند."/><div v-else-if="recent.length" class="account-row-list"><NuxtLink v-for="item in recent" :key="item.post_token" :to="`/v/post/${item.post_token}`"><div><strong>{{item.title}}</strong><small>{{new Date(item.last_viewed_at).toLocaleString('fa-IR')}} · {{Number(item.view_count).toLocaleString('fa-IR')}} بازدید</small></div><span>‹</span></NuxtLink></div><UiState v-else kind="empty" title="بازدیدی ثبت نشده است" description="آگهی‌هایی که مشاهده می‌کنید اینجا نمایش داده می‌شوند."/></AccountShell></template>
